    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_scan_event(ScanEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case ScanEvent_Started(total: final total):
        sse_encode_i_32(0, serializer);
        sse_encode_i_32(total, serializer);
      case ScanEvent_Progress(
        done: final done,
        total: final total,
        current: final current,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_i_32(done, serializer);
        sse_encode_i_32(total, serializer);
        sse_encode_String(current, serializer);
      case ScanEvent_Finished(
        albums: final albums,
        elapsedMs: final elapsedMs,
        rescanned: final rescanned,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_list_album_summary(albums, serializer);
        sse_encode_i_64(elapsedMs, serializer);
        sse_encode_i_32(rescanned, serializer);
    }
  }

  @protected
  void sse_encode_scan_rules(ScanRules self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_String(self.coverKeywords, serializer);
    sse_encode_list_String(self.nameTemplates, serializer);
  }

  @protected
  void sse_encode_track(Track self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.number, serializer);
    sse_encode_String(self.title, serializer);
    sse_encode_opt_String(self.artist, serializer);
    sse_encode_f_64(self.durationSecs, serializer);
    sse_encode_opt_box_autoadd_f_64(self.startSecs, serializer);
    sse_encode_String(self.file, serializer);
    sse_encode_String(self.format, serializer);
    sse_encode_i_32(self.sampleRate, serializer);
    sse_encode_i_32(self.bitDepth, serializer);
    sse_encode_i_32(self.channels, serializer);
  }

